import{_ as o}from"./chunks/gzh.DMj_NaMs.js";import{_ as t,c as r,o as i,ag as l}from"./chunks/framework.BwVZiZlf.js";const e="/weixin.png",b=JSON.parse('{"title":"医博士继续教育学分太难刷？别再手动操作了！我写了个自动化神器","description":"","frontmatter":{"date":"2026-08-31T00:00:00.000Z","tags":["医博士自动化","继续医学教育","RPA","办公提效","效率工具"],"categories":["效率工具"],"sticky":1,"recommend":["自动化","办公"],"cover":"https://img.somenzz.workers.dev/yiboshi-automation-study-tool-cover.png"},"headers":[],"relativePath":"blog/2026/08/31/yiboshi-automation-study-tool.md","filePath":"blog/2026/08/31/yiboshi-automation-study-tool.md","lastUpdated":1788567230000}'),n={name:"blog/2026/08/31/yiboshi-automation-study-tool.md"};function s(p,a,h,d,g,u){return i(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1788134400000"},a[0]||(a[0]=[l('<h1 id="医博士继续教育学分太难刷-别再手动操作了-我写了个自动化神器" tabindex="-1">医博士继续教育学分太难刷？别再手动操作了！我写了个自动化神器 <a class="header-anchor" href="#医博士继续教育学分太难刷-别再手动操作了-我写了个自动化神器" aria-label="Permalink to &quot;医博士继续教育学分太难刷？别再手动操作了！我写了个自动化神器&quot;">​</a></h1><p>兄弟姐妹们，尤其是奋战在一线的医护朋友们：</p><p>你有没有经历过被“继续医学教育（CME）学分”支配的恐惧？</p><p>白天在门诊看病、查房、做手术、写病历，忙得脚后跟打后脑勺；</p><p>好不容易下了夜班想喘口气，或者周末想陪陪家人孩子，结果电脑一开——</p><p><strong>医博士（yiboshi.com）上还有几十个学分、上百门课程、几百个视频等着你“人肉打卡”。</strong></p><p>最要命的是，现在的平台为了防挂机，各种机制层出不穷：</p><ul><li>视频放着放着，冷不丁弹出一个**“您还在继续学习吗？”**，你不点，进度直接卡死；</li><li>刚播完一小节，不会自动跳下一节，非得你手动关掉网页、回到列表、重新找下一节点击播放；</li><li>课后还有各种确认弹窗、答题提示，离开屏幕倒杯水，回来发现 20 分钟全白费了；</li><li>省级项目、国家级项目、全科培训……几百个项目分散在不同分类和分页里，找起来头皮发麻。</li></ul><p>整个人像个提线木偶一样，不得不守在屏幕前，几分钟点一次鼠标。</p><p>这叫什么？</p><p><strong>这叫纯纯的“肉身人肉播放机”，既消耗精力，又浪费生命！</strong></p><hr><h3 id="能用代码解决的-绝不手动死磕" tabindex="-1">能用代码解决的，绝不手动死磕 <a class="header-anchor" href="#能用代码解决的-绝不手动死磕" aria-label="Permalink to &quot;能用代码解决的，绝不手动死磕&quot;">​</a></h3><p>大征哥平时写代码，最见不得这种机械反人类的重复劳动。</p><p>前阵子，我写了不少视频网站和企业级办公系统的 RPA 自动化工具，帮很多做自媒体和行政财务的朋友解决了海量数据提取和视频批量处理的难题，直接给大伙省下了成百上千个小时的宝贵时间。</p><p>当时就有在医院工作的老同学找我诉苦：</p><blockquote><p>“大征哥，你懂自动化，能不能帮我们搞个医博士刷课脚本？我们白天救死扶伤累得要死，晚上还要熬夜盯着屏幕点视频，实在顶不住了！”</p></blockquote><p>我打开医博士的网页后台一看，底层逻辑其实非常清晰：</p><p><strong>无非就是页面状态流转、播放器 DOM 节点监听、防挂机弹窗拦截、列表自动翻页与课程小节调度。</strong></p><p>既然流程是标准化的，凭什么要让治病救人的医生护士把宝贵时间耗在点鼠标上？</p><p><strong>能用代码解决的，绝不手动死磕！</strong></p><p>于是，大征哥花了一周时间，打造了一款<strong>专为医博士继续教育设计的全自动化桌面助手</strong>！</p><hr><h3 id="少啰嗦-先看东西" tabindex="-1">少啰嗦，先看东西！ <a class="header-anchor" href="#少啰嗦-先看东西" aria-label="Permalink to &quot;少啰嗦，先看东西！&quot;">​</a></h3><p>先给兄弟姐妹们上热乎的软件运行界面：</p><p><img src="https://img.somenzz.workers.dev/mian.png" alt="医博士自动化助手桌面端 GUI 界面"></p><p><img src="https://img.somenzz.workers.dev/log.png" alt="实时进度条与彩色运行日志"></p><hr><h3 id="它能为你做什么" tabindex="-1">它能为你做什么？ <a class="header-anchor" href="#它能为你做什么" aria-label="Permalink to &quot;它能为你做什么？&quot;">​</a></h3><p>用最通俗的大白话讲：</p><p><strong>这就相当于给你配了一个不知疲倦的“数字规培助理”，24 小时全自动值守！</strong></p><p>你只需要做一件事：<strong>点一下开始，然后该干嘛干嘛去。</strong></p><p>来看看它的硬核功能有多省心：</p><h4 id="_1-全流程无人值守-大类-➔-项目-➔-视频小节全自动遍历" tabindex="-1">1. 全流程无人值守，大类 ➔ 项目 ➔ 视频小节全自动遍历 <a class="header-anchor" href="#_1-全流程无人值守-大类-➔-项目-➔-视频小节全自动遍历" aria-label="Permalink to &quot;1. 全流程无人值守，大类 ➔ 项目 ➔ 视频小节全自动遍历&quot;">​</a></h4><ul><li>自动进入学习中心，逐一扫描你的课程大类（省级、国家级、乡村医生培训等）；</li><li>自动识别“学习中”和“未学习”项目，支持自动点击【+添加到我的项目中】并自动开课；</li><li>当前小节达标 100% 自动关闭并顺畅切入下一节；</li><li>一整页学完了，自动识别分页器并点击翻页，完全不用人工干预！</li></ul><h4 id="_2-智能秒解防挂机弹窗与暂停" tabindex="-1">2. 智能秒解防挂机弹窗与暂停 <a class="header-anchor" href="#_2-智能秒解防挂机弹窗与暂停" aria-label="Permalink to &quot;2. 智能秒解防挂机弹窗与暂停&quot;">​</a></h4><ul><li>视频播放过程中弹出的**“继续学习”、“继续观看”、“温馨提示”、“确定”**等干扰弹窗，脚本毫秒级自动识别并点击确认；</li><li>播放器异常暂停时，自动唤醒播放，杜绝卡进度现象。</li></ul><h4 id="_3-本地达标缓存-实时-dom-双重校验-绝不重复刷" tabindex="-1">3. 本地达标缓存 + 实时 DOM 双重校验（绝不重复刷） <a class="header-anchor" href="#_3-本地达标缓存-实时-dom-双重校验-绝不重复刷" aria-label="Permalink to &quot;3. 本地达标缓存 + 实时 DOM 双重校验（绝不重复刷）&quot;">​</a></h4><ul><li>内置进度持久化机制，本地自动记录已完成的小节；</li><li>结合页面 DOM 实时百分比（<code>视频达标要求：100% 已完成：100%</code>），已达标课程<strong>秒级跳过</strong>，绝不浪费 1 秒钟重复播放；</li><li>随时可以按 <code>⏹ 停止</code>，下次启动<strong>无缝断点续学</strong>。</li></ul><h4 id="_4-一次扫码-永久免密-登录态持久化" tabindex="-1">4. 一次扫码，永久免密（登录态持久化） <a class="header-anchor" href="#_4-一次扫码-永久免密-登录态持久化" aria-label="Permalink to &quot;4. 一次扫码，永久免密（登录态持久化）&quot;">​</a></h4><ul><li>首次启动支持微信扫码或手机验证码登录；</li><li>登录成功后自动保存 Session 凭据，下次打开软件直接进入学习，告别频繁扫码烦恼。</li></ul><h4 id="_5-后台静默运行-无头模式" tabindex="-1">5. 后台静默运行（无头模式） <a class="header-anchor" href="#_5-后台静默运行-无头模式" aria-label="Permalink to &quot;5. 后台静默运行（无头模式）&quot;">​</a></h4><ul><li>勾选【后台静默运行】后，浏览器在后台静默跑课；</li><li>完全不占屏幕、不抢鼠标焦点，前台你可以正常写病历、开处方、办公、追剧或者玩游戏，互不干扰！</li></ul><h4 id="_6-极简-gui-桌面端-开箱即用" tabindex="-1">6. 极简 GUI 桌面端，开箱即用 <a class="header-anchor" href="#_6-极简-gui-桌面端-开箱即用" aria-label="Permalink to &quot;6. 极简 GUI 桌面端，开箱即用&quot;">​</a></h4><ul><li>告别复杂的命令行与 Python 环境配置，独立桌面图形界面；</li><li>仪表盘清晰呈现：<strong>当前大类、当前项目、当前小节、已播百分比与倒计时进度条</strong>；</li><li>状态一目了然，小白也能轻松上手。</li></ul><hr><h3 id="极简使用工作流-只需三步" tabindex="-1">极简使用工作流（只需三步） <a class="header-anchor" href="#极简使用工作流-只需三步" aria-label="Permalink to &quot;极简使用工作流（只需三步）&quot;">​</a></h3><ol><li><strong>双击启动软件</strong>：打开可视化主界面；</li><li><strong>选择目标分类</strong>（可选）：可在下拉框中指定学习某个特定专区，也可以直接留空遍历全部；</li><li><strong>点击【▶ 开始自动化学习】</strong>：首次扫码登录后，即可甩手去喝茶、写病历或者睡觉，软件全自动搞定一切！</li></ol><hr><h3 id="时间就是金钱-工具放大价值" tabindex="-1">时间就是金钱，工具放大价值 <a class="header-anchor" href="#时间就是金钱-工具放大价值" aria-label="Permalink to &quot;时间就是金钱，工具放大价值&quot;">​</a></h3><p>咱们医护人员的时间，是按分钟计算的黄金资产。</p><p>一个继续教育周期下来，少则几十个小时，多则上百个小时：</p><ul><li>如果人工盯着刷，你要白白搭进去几十个宝贵的下班夜晚或周末休息时间；</li><li>遇到漏刷、进度没达标导致学分审核不过，还会直接影响当年的评优、考核与职称晋升！</li></ul><p>大征哥做独立开发，向来坚持最坦荡的双赢逻辑：</p><p><strong>我用扎实可靠的极客技术帮你干掉反人类的机械重复，帮你把宝贵的时间抢回来，去治病救人、去陪伴家人、去好好睡个安稳觉；你为好用的生产力工具买单，支持我持续维护和升级。</strong></p><hr><h3 id="如何获取软件与技术支持" tabindex="-1">如何获取软件与技术支持？ <a class="header-anchor" href="#如何获取软件与技术支持" aria-label="Permalink to &quot;如何获取软件与技术支持？&quot;">​</a></h3><p>想要体验或购买医博士自动化学习助手的兄弟姐妹们：</p><p>👉 <strong>欢迎添加大征哥个人微信</strong>：备注【<strong>医博士</strong>】，获取专属安装包、使用教程与激活授权。 <img src="'+e+'" alt="大征哥微信"></p><p>👉 <strong>个人技术主页</strong>：欢迎访问 <a href="https://dazhengs.github.io" target="_blank" rel="noreferrer">大征哥的技术博客</a>，了解更多自研办公提效、RPA 自动化、OCR 识别等黑科技工具。</p><p>👉 <strong>关注公众号</strong>：微信搜索关注【<strong>大征哥</strong>】，第一时间获取最新自动化工具与极客提效玩法！</p><p><img src="'+o+'" alt="大征哥公众号"></p><hr><h3 id="尾声" tabindex="-1">尾声 <a class="header-anchor" href="#尾声" aria-label="Permalink to &quot;尾声&quot;">​</a></h3><p>最后，还是大征哥常挂在嘴边的那句话：</p><p><strong>“能让机器干的活，人就该去喝茶。”</strong></p><p>医生的双手是用来拿手术刀、救死扶伤的，而不是留在电脑前当机械点鼠标的“人肉工具人”。</p><p>把重复乏味的刷课苦力交给自动化代码，把时间和精力留给专业技能、健康和生活本身。</p><p>兄弟姐妹们，<strong>你们在日常医院办公、科室填表、考勤培训或各类系统打卡中，还有哪些特别头疼、耗时又反人类的重复操作？</strong></p><p>欢迎在评论区给大征哥留言！点赞留言最多的痛点需求，下期大征哥直接写成自动化神器安排上！</p>',70)]))}const _=t(n,[["render",s]]);export{b as __pageData,_ as default};
